#include <vector>
#include <unordered_set>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minimumTeachings(int n, vector<vector<int>>& languages, vector<vector<int>>& friendships) {
        int m = languages.size();
        vector<unordered_set<int>> lang_sets(m);
        for (int i = 0; i < m; ++i) {
            for (int l : languages[i]) lang_sets[i].insert(l);
        }
        unordered_set<int> broken_users;
        for (const auto& f : friendships) {
            int u = f[0] - 1, v = f[1] - 1;
            bool ok = false;
            for (int l : lang_sets[u]) {
                if (lang_sets[v].count(l)) { ok = true; break; }
            }
            if (!ok) {
                broken_users.insert(u);
                broken_users.insert(v);
            }
        }
        if (broken_users.empty()) return 0;
        int ans = broken_users.size();
        for (int l = 1; l <= n; ++l) {
            int teach = 0;
            for (int u : broken_users) {
                if (!lang_sets[u].count(l)) teach++;
            }
            ans = min(ans, teach);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minimumTeachings(int n, int[][] languages, int[][] friendships) {
        int m = languages.length;
        List<Set<Integer>> langSets = new ArrayList<>();
        for (int[] langs : languages) {
            Set<Integer> set = new HashSet<>();
            for (int l : langs) set.add(l);
            langSets.add(set);
        }
        Set<Integer> brokenUsers = new HashSet<>();
        for (int[] f : friendships) {
            int u = f[0] - 1, v = f[1] - 1;
            boolean ok = false;
            for (int l : langSets.get(u)) {
                if (langSets.get(v).contains(l)) { ok = true; break; }
            }
            if (!ok) {
                brokenUsers.add(u);
                brokenUsers.add(v);
            }
        }
        if (brokenUsers.isEmpty()) return 0;
        int ans = brokenUsers.size();
        for (int l = 1; l <= n; ++l) {
            int teach = 0;
            for (int u : brokenUsers) {
                if (!langSets.get(u).contains(l)) teach++;
            }
            ans = Math.min(ans, teach);
        }
        return ans;
    }
}

/**
 * @param {number} n
 * @param {number[][]} languages
 * @param {number[][]} friendships
 * @return {number}
 */
var minimumTeachings = function(n, languages, friendships) {
    const langSets = languages.map(langs => new Set(langs));
    const brokenUsers = new Set();
    for (const [u, v] of friendships) {
        const uIdx = u - 1, vIdx = v - 1;
        let ok = false;
        for (const l of langSets[uIdx]) {
            if (langSets[vIdx].has(l)) { ok = true; break; }
        }
        if (!ok) {
            brokenUsers.add(uIdx);
            brokenUsers.add(vIdx);
        }
    }
    if (brokenUsers.size === 0) return 0;
    let ans = brokenUsers.size;
    for (let l = 1; l <= n; ++l) {
        let teach = 0;
        for (const u of brokenUsers) {
            if (!langSets[u].has(l)) teach++;
        }
        ans = Math.min(ans, teach);
    }
    return ans;
};
